document.addEventListener('DOMContentLoaded', () => {
    const width = document.getElementById('bubble-chart').clientWidth;
    const height = document.getElementById('bubble-chart').clientHeight || 600;

    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("width", "100%")
        .attr("height", height)
        .attr("viewBox", `0 0 ${width} ${height}`);

    const tooltip = d3.select("#tooltip");

    function formatMarketCap(value) {
        if (!value || isNaN(value) || value === "") return "N/A";
        const val = parseFloat(value);
        if (isNaN(val)) return "N/A";

        const suffixes = ["", "K", "M", "B", "T"];
        let suffixNum = 0;
        let tempVal = val;
        while (tempVal >= 1000 && suffixNum < suffixes.length - 1) {
            tempVal /= 1000;
            suffixNum++;
        }
        return tempVal.toFixed(2) + suffixes[suffixNum];
    }

    d3.csv("data/stock-descriptions.csv").then(data => {
        // Data cleaning
        data.forEach(d => {
            d.marketCap = d.marketCap ? parseFloat(d.marketCap) : null;
            d.isETF = !d.marketCap;
        });

        // Filter out empty rows if any (though d3.csv usually handles it)
        data = data.filter(d => d.ticker);

        const sectors = [...new Set(data.map(d => d.sector))].sort();
        const colorScale = d3.scaleOrdinal(d3.schemeCategory10)
            .domain(sectors);

        // Define radius scale
        const minRadius = 20;
        const maxRadius = 60;
        const etfRadius = 25;

        const capExtent = d3.extent(data.filter(d => !d.isETF), d => d.marketCap);
        const radiusScale = d3.scaleSqrt()
            .domain(capExtent)
            .range([minRadius, maxRadius]);

        data.forEach(d => {
            d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
        });

        // Legend
        const legendContainer = d3.select("#legend");
        sectors.forEach(sector => {
            const item = legendContainer.append("div").attr("class", "legend-item");
            item.append("div")
                .attr("class", "legend-color")
                .style("background-color", colorScale(sector));
            item.append("span").text(sector || "Unknown");
        });

        // Force Simulation
        const sectorCenters = {};
        const radius = Math.min(width, height) * 0.3;
        sectors.forEach((sector, i) => {
            const angle = (i / sectors.length) * 2 * Math.PI;
            sectorCenters[sector] = {
                x: width / 2 + Math.cos(angle) * radius,
                y: height / 2 + Math.sin(angle) * radius
            };
        });

        const simulation = d3.forceSimulation(data)
            .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.15))
            .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.15))
            .force("collide", d3.forceCollide(d => d.radius + 2))
            .force("charge", d3.forceManyBody().strength(-10))
            .force("center", d3.forceCenter(width / 2, height / 2));

        const bubbles = svg.selectAll(".bubble-group")
            .data(data)
            .enter()
            .append("g")
            .attr("class", "bubble-group")
            .on("click", (event, d) => highlightStock(d.ticker, true))
            .on("mouseover", (event, d) => {
                if (!d.isETF) {
                    tooltip.style("display", "block")
                        .html(`<strong>${d.ticker}</strong><br>${d['full name']}<br>${d.sector}`);
                }
            })
            .on("mousemove", (event) => {
                tooltip.style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY - 10) + "px");
            })
            .on("mouseout", () => {
                tooltip.style("display", "none");
            });

        bubbles.append("circle")
            .attr("class", "bubble")
            .attr("id", d => `bubble-${d.ticker}`)
            .attr("r", d => d.radius)
            .attr("fill", d => colorScale(d.sector));

        bubbles.append("text")
            .attr("class", "label")
            .text(d => d.ticker)
            .attr("dy", ".3em");

        simulation.on("tick", () => {
            bubbles.attr("transform", d => `translate(${d.x},${d.y})`);
        });

        // Table
        const tbody = d3.select("#stock-table tbody");
        const rows = tbody.selectAll("tr")
            .data(data)
            .enter()
            .append("tr")
            .attr("id", d => `row-${d.ticker}`)
            .on("click", (event, d) => highlightStock(d.ticker, false));

        rows.append("td").text(d => d.ticker);
        rows.append("td").text(d => d['full name']);
        rows.append("td").text(d => d.sector);
        rows.append("td").text(d => formatMarketCap(d.marketCap));

        function highlightStock(ticker, fromChart) {
            // Remove previous highlights
            d3.selectAll(".bubble").classed("highlighted", false);
            d3.selectAll("tr").classed("highlighted", false);

            // Add new highlights
            d3.select(`#bubble-${ticker}`).classed("highlighted", true);
            const row = d3.select(`#row-${ticker}`);
            row.classed("highlighted", true);

            // Scroll table if needed
            if (fromChart) {
                const rowNode = row.node();
                if (rowNode) {
                    rowNode.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                }
            }
        }
    });
});

