        const val = parseFloat(value);
        if (isNaN(val)) return "N/A";

        const suffixes = ["", "K", "M", "B", "T"];
        let suffixNum = 0;
        let tempVal = val;
        while (tempVal >= 1000 && suffixNum < suffixes.length - 1) {
            tempVal /= 1000;
            suffixNum++;
        }
        return tempVal.toFixed(2) + suffixes[suffixNum];
    }

    d3.csv("data/stock-descriptions.csv").then(data => {
        // Data cleaning
        data = data.filter(d => d.ticker && d.ticker.trim() !== "");

        data.forEach(d => {
            const capStr = d.marketCap;
            if (capStr && capStr.trim() !== "") {
                d.marketCap = parseFloat(capStr);
            } else {
                d.marketCap = null;
            }
            d.isETF = (d.marketCap === null || d.sector === "ETF");
        });

        const sectors = [...new Set(data.map(d => d.sector))].sort();
        // Use a larger color scheme if needed
        const colorScale = d3.scaleOrdinal(d3.schemeTableau10)
            .domain(sectors);

        // Define radius scale
        const minRadius = 15;
        const maxRadius = 50;
        const etfRadius = 20;

        const validCaps = data.filter(d => !d.isETF).map(d => d.marketCap);
        const capExtent = d3.extent(validCaps);
        const radiusScale = d3.scaleSqrt()
            .domain(capExtent[0] ? capExtent : [1e9, 3e12]) // fallback if no valid caps
            .range([minRadius, maxRadius]);

        data.forEach(d => {
            d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
        });

        // Legend
        const legendContainer = d3.select("#legend");
        sectors.forEach(sector => {
            const item = legendContainer.append("div").attr("class", "legend-item");
            item.append("div")
                .attr("class", "legend-color")
                .style("background-color", colorScale(sector));
            item.append("span").text(sector || "Unknown");
        });

