            .text(d => d.ticker)
            .attr("dy", ".3em")
            .style("font-size", d => Math.min(d.radius / 2, 12) + "px");

        simulation.on("tick", () => {
            bubbles.attr("transform", d => `translate(${d.x},${d.y})`);
        });

        // Table
        const tbody = d3.select("#stock-table tbody");
        const rows = tbody.selectAll("tr")
            .data(data)
            .enter()
            .append("tr")
            .attr("id", d => `row-${d.ticker}`)
            .on("click", (event, d) => highlightStock(d.ticker, false));

        rows.append("td").text(d => d.ticker);
        rows.append("td").text(d => d['full name']);
        rows.append("td").text(d => d.sector);
        rows.append("td").text(d => formatMarketCap(d.marketCap));

